  window.getFallbackDay = function(role, dayIndex) {
    if (!window.LOCAL_FALLBACK_TRACKS) return null;
    var r = (role || 'Mentora').toLowerCase();
    var isMentada = r.indexOf('mentada') !== -1 || r.indexOf('mentoreada') !== -1;
    var track = isMentada ? window.LOCAL_FALLBACK_TRACKS.Mentada : window.LOCAL_FALLBACK_TRACKS.Mentora;
    if (!track) return null;
    var num = Number(dayIndex);
    for (var i = 0; i < track.length; i++) {
      if (track[i].dia === num) return track[i];
    }
    return null;
  };

